export default function Loader() {
    const [progress, setProgress] = useState(0);
    const [loading, setLoading] = useState(true);

    const loaderRef = useRef<HTMLDivElement>(null);
    const logoRef = useRef<HTMLDivElement>(null);
    const topRef = useRef<HTMLDivElement>(null);
    const bottomRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        let current = 0;

        const interval = setInterval(() => {
            current += Math.random() * 3;

            if (current >= 100) {
                current = 100;
                clearInterval(interval);

                setProgress(100);

                // Give the fully loaded logo a small moment
                setTimeout(() => {
                    revealWebsite();
                }, 500);
            }

            setProgress(current);
        }, 40);

        return () => clearInterval(interval);
    }, []);

    const revealWebsite = () => {
        const tl = gsap.timeline({
            onComplete: () => {
                setLoading(false);

                // Tell AOS that the loader has finished
                window.dispatchEvent(new Event("loaderComplete"));
            },
        });

        // Fade logo
        tl.to(logoRef.current, {
            opacity: 0,
            duration: 0.45,
            ease: "power2.inOut",
        });

        // Move top panel
        tl.to(
            topRef.current,
            {
                yPercent: -100,
                duration: 1,
                ease: "power4.inOut",
            },
            "<"
        );

        // Move bottom panel
        tl.to(
            bottomRef.current,
            {
                yPercent: 100,
                duration: 1,
                ease: "power4.inOut",
            },
            "<"
        );
    };

    if (!loading) return null;

    return (
        <div
            ref={loaderRef}
            className="fixed inset-0 z-9999 overflow-hidden"
        >
            {/* TOP PANEL */}
            <div
                ref={topRef}
                className="
                    absolute
                    top-0
                    left-0
                    w-full
                    h-1/2
                    bg-(--primary-color)
                "
            />

            {/* BOTTOM PANEL */}
            <div
                ref={bottomRef}
                className="
                    absolute
                    bottom-0
                    left-0
                    w-full
                    h-1/2
                    bg-(--primary-color)
                "
            />

            {/* LOGO */}
            <div
                ref={logoRef}
                className="
                    absolute
                    z-10
                    top-1/2
                    left-1/2
                    -translate-x-1/2
                    -translate-y-1/2
                    w-75
                "
            >
                {/* Base SVG — 50% opacity */}
                <div className="text-white opacity-50">
                    <LogoSvg />
                </div>

                {/* Loaded SVG — revealed according to progress */}
                <div
                    className="
                        absolute
                        inset-0
                        overflow-hidden
                    "
                    style={{
                        width: `${progress}%`,
                    }}
                >
                    <div
                        className="
                            absolute
                            top-0
                            left-0
                            w-75
                            max-w-none
                            text-white
                        "
                    >
                        <LogoSvg />
                    </div>
                </div>
            </div>
        </div>
    );
}